package de.fitnesscoach.data.dao;
import androidx.room.*;import java.time.*;import java.util.*;import de.fitnesscoach.data.entity.*;
@Dao public interface WorkoutDao{@Insert(onConflict=OnConflictStrategy.ABORT)long insertWorkout(WorkoutEntity e);@Update void updateWorkout(WorkoutEntity e);@Query("SELECT * FROM workouts WHERE externalRecordId = :id LIMIT 1")WorkoutEntity getByExternalRecordId(String id);@Query("SELECT * FROM workouts ORDER BY startTime DESC")List<WorkoutEntity>getWorkouts();@Query("SELECT * FROM workouts WHERE startTime < :endExclusive AND endTime > :startInclusive ORDER BY startTime")List<WorkoutEntity>workoutsOverlapping(Instant startInclusive,Instant endExclusive);@Insert(onConflict=OnConflictStrategy.ABORT)long insertPlanned(PlannedWorkoutEntity e);@Update void updatePlanned(PlannedWorkoutEntity e);@Query("SELECT * FROM planned_workouts WHERE date BETWEEN :from AND :to ORDER BY date")List<PlannedWorkoutEntity>plannedRange(LocalDate from,LocalDate to);@Query("SELECT * FROM planned_workouts WHERE id=:id LIMIT 1")PlannedWorkoutEntity getPlanned(long id);}
